/*
 * ESP32 BMP280 — temperature, pressure, and altitude
 *
 * The simulator reads environmental values from the BME280 canvas
 * component. Adjust its Temp and Press controls while the sketch runs.
 * ESP32 I2C defaults: SDA GPIO21 and SCL GPIO22.
 */
#include <Wire.h>
#include <Adafruit_BMP280.h>

Adafruit_BMP280 bmp;

void setup() {
  Serial.begin(115200);
  Wire.begin(21, 22);

  if (!bmp.begin(0x76)) {
    Serial.println("BMP280 sensor not found on the canvas");
    return;
  }
  Serial.println("BMP280 ready");
}

void loop() {
  Serial.print("Temperature: ");
  Serial.print(bmp.readTemperature(), 1);
  Serial.println(" C");

  Serial.print("Pressure: ");
  Serial.print(bmp.readPressure() / 100.0, 1);
  Serial.println(" hPa");

  Serial.print("Approx. altitude: ");
  Serial.print(bmp.readAltitude(1013.25), 1);
  Serial.println(" m");
  Serial.println();
  delay(2000);
}
